3	/// An always-available "remote keyboard" docked under the focused terminal.
4	///
5	/// The terminal pane already renders cmux/Claude's own input line, so this bar
6	/// is deliberately styled as distinct keyboard chrome (not glass-terminal) to
7	/// read as *your* input bridge rather than a second prompt. It stays collapsed
8	/// to a slim field until tapped, then reveals command autocomplete and a
9	/// control-key row. It clears on send — the terminal's output remains the one
10	/// source of truth for what was typed.
11	struct TerminalInputBar: View {
12	    let surfaceTitle: String
13	    /// Reflects keyboard/compose focus up to the parent so it can give the
14	    /// focused terminal the whole screen while typing.
15	    @Binding var isActive: Bool
16	    var onSendText: (String) -> Void   // send text only (no newline)
17	    var onSendEnter: (String) -> Void  // send text + Enter (run it)
18	    var onSendKey: (String) -> Void    // send a control/navigation key
19	
20	    @State private var draft = ""
21	    @FocusState private var focused: Bool
22	    @StateObject private var commandDict = CommandDictionary()
23	    // Landscape on iPhone reports a compact vertical size class. There the
24	    // keyboard eats most of the height, so the bar shrinks to a single chip
25	    // row + inline dismiss to leave room for the terminal.
26	    @Environment(\.verticalSizeClass) private var vSizeClass
27	    private var isCompact: Bool { vSizeClass == .compact }
28	
29	    // A control chip either fires a named key via the bridge (`surface.send_key`,
30	    // matching SendTextView conventions) or injects literal text. cmux has no
31	    // key-name for the spacebar, so Space is sent as a literal " ".
32	    private enum KeyAction {
33	        case key(String)
34	        case text(String)
35	    }
36	
37	    private struct ControlKey: Identifiable {
38	        let label: String
39	        let action: KeyAction
40	        // Lowercase aliases the compose field can filter on as you type.
41	        let terms: [String]
42	        // Space gets a wider chip so it reads as a spacebar.
43	        var isWide: Bool = false
44	        var id: String { label }
45	    }
46	
47	    // Merged from the quick-actions "Input" section so the remote keyboard is a
48	    // superset of the popup — plus a spacebar the popup never had.
49	    private let controlKeys: [ControlKey] = [
50	        ControlKey(label: "esc", action: .key("Escape"), terms: ["esc", "escape"]),
51	        ControlKey(label: "⏎",   action: .key("enter"),  terms: ["enter", "return", "cr"]),
52	        ControlKey(label: "␣",   action: .text(" "),     terms: ["space", "spacebar", "spc"], isWide: true),
53	        ControlKey(label: "⇥",   action: .key("Tab"),    terms: ["tab"]),
54	        ControlKey(label: "⌃C",  action: .key("ctrl+c"), terms: ["ctrl+c", "ctrlc", "^c", "interrupt"]),
55	        ControlKey(label: "⌃D",  action: .key("ctrl+d"), terms: ["ctrl+d", "ctrld", "^d", "eof"]),
56	        ControlKey(label: "⌃Z",  action: .key("ctrl+z"), terms: ["ctrl+z", "ctrlz", "^z", "suspend"]),
57	        ControlKey(label: "⌃L",  action: .key("ctrl+l"), terms: ["ctrl+l", "ctrll", "^l", "clear"]),
58	        ControlKey(label: "↑",   action: .key("Up"),     terms: ["up", "arrow"]),
59	        ControlKey(label: "↓",   action: .key("Down"),   terms: ["down", "arrow"]),
60	        ControlKey(label: "←",   action: .key("Left"),   terms: ["left", "arrow"]),
61	        ControlKey(label: "→",   action: .key("Right"),  terms: ["right", "arrow"]),
62	    ]
63	
64	    // The word being typed in the compose field doubles as a live filter for the
65	    // control chips (mirrors how command suggestions filter). If the word matches
66	    // no key it isn't a key query — a normal command — so we fall back to the full
67	    // row and keep navigation keys reachable while composing.
68	    private var filteredControlKeys: [ControlKey] {
69	        let q = currentWord.lowercased()
70	        guard !q.isEmpty else { return controlKeys }
71	        let matches = controlKeys.filter { ck in
72	            ck.label.lowercased().hasPrefix(q) || ck.terms.contains { $0.hasPrefix(q) }
73	        }
74	        return matches.isEmpty ? controlKeys : matches
75	    }
76	
77	    var body: some View {
78	        VStack(spacing: isCompact ? 4 : 6) {
79	            if focused {
80	                if isCompact {
81	                    // One merged, scrollable row keeps the footprint minimal.
82	                    compactChipsRow
83	                } else {
84	                    header
85	                    suggestionsRow
86	                    controlKeyRow
87	                }
88	            }
89	            composeRow
90	        }
91	        .padding(.horizontal, 10)
92	        .padding(.vertical, isCompact ? 6 : 8)
93	        .background(
94	            RoundedRectangle(cornerRadius: 14)
95	                .fill(.ultraThinMaterial)
96	                .environment(\.colorScheme, .dark)
97	                .overlay(
98	                    RoundedRectangle(cornerRadius: 14)
99	                        .stroke(.white.opacity(0.12), lineWidth: 0.5)
100	                )
101	        )
102	        .padding(.horizontal, 8)
103	        .animation(.easeInOut(duration: 0.18), value: focused)
104	        .onChange(of: focused) { _, active in isActive = active }
105	        // If the bar is torn down while focused (quick actions open, the focused
106	        // surface closes or becomes a browser, tab switch), `.onChange(of:focused)`
107	        // won't fire — so reset here, or the parent leaves the workspace bar and
108	        // secondaries hidden forever.
109	        .onDisappear { isActive = false }
110	    }
111	
112	    // MARK: - Header (only while composing)
113	
114	    private var header: some View {
115	        HStack(spacing: 6) {
116	            Image(systemName: "terminal")
117	                .font(.system(size: 10))
118	                .foregroundStyle(.white.opacity(0.35))
119	            Text(surfaceTitle.isEmpty ? "terminal" : surfaceTitle)
120	                .font(.system(size: 11, weight: .medium, design: .monospaced))
121	                .foregroundStyle(.white.opacity(0.5))
122	                .lineLimit(1)
123	                .truncationMode(.middle)
