141	    // MARK: - Compose row
142	
143	    private var composeRow: some View {
144	        HStack(spacing: 8) {
145	            Image(systemName: "keyboard")
146	                .font(.system(size: 14))
147	                .foregroundStyle(.white.opacity(0.4))
148	
149	            TextField("", text: $draft, axis: .vertical)
150	                .focused($focused)
151	                .lineLimit(1...4)
152	                .font(.system(size: 14, design: .monospaced))
153	                .foregroundStyle(.white)
154	                .tint(.green)
155	                .autocorrectionDisabled()
156	                .textInputAutocapitalization(.never)
157	                .overlay(alignment: .leading) {
158	                    if draft.isEmpty {
159	                        Text("Send to \(surfaceTitle.isEmpty ? "terminal" : surfaceTitle)…")
160	                            .font(.system(size: 14, design: .monospaced))
161	                            .foregroundStyle(.white.opacity(0.3))
162	                            .allowsHitTesting(false)
163	                    }
164	                }
165	
166	            if !draft.isEmpty {
167	                Button {
168	                    send(withEnter: false)
169	                } label: {
170	                    Image(systemName: "paperplane")
171	                        .font(.system(size: 15))
172	                        .foregroundStyle(.white.opacity(0.6))
173	                }
174	                Button {
175	                    send(withEnter: true)
176	                } label: {
177	                    Image(systemName: "return")
178	                        .font(.system(size: 15, weight: .semibold))
179	                        .foregroundStyle(.green)
180	                }
181	            }
182	
183	            // Compact mode has no header, so the dismiss lives inline here.
184	            if isCompact && focused {
185	                Button {
186	                    focused = false
187	                } label: {
188	                    Image(systemName: "keyboard.chevron.compact.down")
189	                        .font(.system(size: 16, weight: .semibold))
190	                        .foregroundStyle(.white.opacity(0.7))
191	                }
192	                .padding(.leading, 2)
193	            }
194	        }
195	    }
