197	    // MARK: - Command suggestions
198	
199	    private var currentWord: String {
200	        let trimmed = draft.replacingOccurrences(of: "\n", with: " ")
201	        return trimmed.split(separator: " ").last.map(String.init) ?? ""
202	    }
203	
204	    private var suggestionsRow: some View {
205	        ScrollView(.horizontal, showsIndicators: false) {
206	            HStack(spacing: 8) {
207	                ForEach(commandDict.suggestions(for: currentWord), id: \.self) { cmd in
208	                    suggestionChip(cmd)
209	                }
210	            }
211	            .padding(.horizontal, 2)
212	        }
213	        .frame(height: 30)
214	    }
215	
216	    // MARK: - Control keys
217	
218	    private var controlKeyRow: some View {
219	        ScrollView(.horizontal, showsIndicators: false) {
220	            HStack(spacing: 6) {
221	                ForEach(filteredControlKeys) { ck in
222	                    controlChip(ck)
223	                }
224	            }
225	            .padding(.horizontal, 2)
226	        }
227	        .frame(height: 32)
228	    }
229	
230	    // MARK: - Compact chips (landscape)
231	
232	    // Suggestions + control keys merged into a single scrollable row so the
233	    // whole bar is just this row + the compose row when the keyboard is up.
234	    private var compactChipsRow: some View {
235	        ScrollView(.horizontal, showsIndicators: false) {
236	            HStack(spacing: 6) {
237	                ForEach(commandDict.suggestions(for: currentWord), id: \.self) { cmd in
238	                    suggestionChip(cmd)
239	                }
240	                ForEach(filteredControlKeys) { ck in
241	                    controlChip(ck)
242	                }
243	            }
244	            .padding(.horizontal, 2)
245	        }
246	        .frame(height: 30)
247	    }
248	
249	    private func suggestionChip(_ cmd: String) -> some View {
250	        Button {
251	            insertSuggestion(cmd)
252	        } label: {
253	            Text(cmd)
254	                .font(.system(size: 12, weight: .medium, design: .monospaced))
255	                .foregroundStyle(.white.opacity(0.85))
256	                .padding(.horizontal, 10)
257	                .padding(.vertical, 5)
258	                .background(Capsule().fill(.white.opacity(0.1)))
259	        }
260	    }
261	
262	    private func controlChip(_ ck: ControlKey) -> some View {
263	        Button {
264	            fire(ck)
265	        } label: {
266	            Text(ck.label)
267	                .font(.system(size: 13, weight: .medium, design: .monospaced))
268	                .foregroundStyle(.white.opacity(0.75))
269	                .frame(minWidth: ck.isWide ? 72 : 34)
270	                .padding(.vertical, 6)
271	                .background(RoundedRectangle(cornerRadius: 7).fill(.white.opacity(0.08)))
272	        }
273	    }
274	
275	    private func fire(_ ck: ControlKey) {
276	        switch ck.action {
277	        case .key(let key):   onSendKey(key)
278	        case .text(let text): onSendText(text)
279	        }
280	    }
281	
282	    // MARK: - Actions
283	
284	    private func send(withEnter: Bool) {
285	        let text = draft
286	        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
287	        learnCommand(text)
288	        if withEnter {
289	            onSendEnter(text)
290	        } else {
291	            onSendText(text)
292	        }
293	        draft = ""
294	        // Keep the keyboard up so the user can fire off several commands.
295	    }
296	
297	    private func insertSuggestion(_ command: String) {
298	        let parts = draft.split(separator: " ", omittingEmptySubsequences: false).map(String.init)
299	        if parts.isEmpty {
300	            draft = command + " "
301	        } else {
302	            var updated = parts
303	            updated[updated.count - 1] = command
304	            draft = updated.joined(separator: " ") + " "
305	        }
306	    }
307	
308	    private func learnCommand(_ input: String) {
309	        let firstWord = input.trimmingCharacters(in: .whitespacesAndNewlines)
310	            .split(separator: " ").first.map(String.init) ?? ""
311	        if !firstWord.isEmpty { commandDict.add(firstWord) }
312	    }
313	}
