14	enum QuickActionBuilder {
15	    @MainActor
16	    static func build(surfaceID sid: String, appState: AppState, store: QuickActionStore, onToggleFullscreen: @escaping () -> Void = {}) -> [QuickAction] {
17	        let builtIn: [QuickAction] = [
18	            QuickAction(label: "Enter", icon: "return", section: "Input") {
19	                appState.sendKey("enter", to: sid)
20	            },
21	            QuickAction(label: "Ctrl+C", icon: "xmark.circle", section: "Input") {
22	                appState.sendKey("ctrl+c", to: sid)
23	            },
24	            QuickAction(label: "Ctrl+D", icon: "eject", section: "Input") {
25	                appState.sendKey("ctrl+d", to: sid)
26	            },
27	            QuickAction(label: "Ctrl+Z", icon: "pause.circle", section: "Input") {
28	                appState.sendKey("ctrl+z", to: sid)
29	            },
30	            QuickAction(label: "Clear", icon: "trash", section: "Input") {
31	                appState.sendKey("ctrl+l", to: sid)
32	            },
33	            QuickAction(label: "Tab", icon: "arrow.right.to.line", section: "Input") {
34	                appState.sendKey("tab", to: sid)
35	            },
36	            QuickAction(label: "Escape", icon: "escape", section: "Input") {
37	                appState.sendKey("escape", to: sid)
38	            },
39	            QuickAction(label: "Up Arrow", icon: "arrow.up", section: "Input") {
40	                appState.sendKey("up", to: sid)
41	            },
42	            QuickAction(label: "Down Arrow", icon: "arrow.down", section: "Input") {
43	                appState.sendKey("down", to: sid)
44	            },
45	            QuickAction(label: "Split Right", icon: "rectangle.split.2x1", section: "Terminal") {
46	                appState.splitSurface(direction: "right", surfaceID: sid)
47	            },
48	            QuickAction(label: "Split Down", icon: "rectangle.split.1x2", section: "Terminal") {
49	                appState.splitSurface(direction: "down", surfaceID: sid)
50	            },
51	            QuickAction(label: "New Terminal", icon: "plus.rectangle", section: "Terminal") {
52	                appState.createSurface()
53	            },
54	            QuickAction(label: "Close Surface", icon: "xmark.rectangle", section: "Terminal") {
55	                appState.closeSurface(sid)
56	            },
57	            QuickAction(label: "Zoom", icon: "arrow.up.left.and.arrow.down.right", section: "Terminal") {
58	                appState.togglePaneZoom(sid)
59	            },
60	            QuickAction(label: "New Workspace", icon: "square.grid.2x2", section: "Workspace") {
61	                appState.createWorkspace()
62	            },
63	            QuickAction(label: "Fullscreen", icon: "rectangle.fill", section: "Workspace") {
64	                onToggleFullscreen()
65	            },
66	            QuickAction(label: "Close Workspace", icon: "xmark.square", section: "Workspace") {
67	                if let wsID = appState.currentWorkspaceID {
68	                    appState.closeWorkspace(wsID)
69	                }
70	            },
71	        ]
72	
73	        // Filter out hidden built-in actions
74	        var result = builtIn.filter { !store.isBuiltInHidden($0.label) }
75	
76	        // Append visible custom actions
77	        for custom in store.customActions where !custom.isHidden {
78	            result.append(QuickAction(label: custom.label, icon: custom.icon, section: custom.section) {
79	                appState.sendText(custom.command, to: sid)
80	            })
81	        }
82	
83	        return result
84	    }
85	}
