87	@MainActor
88	final class QuickActionState: ObservableObject {
89	    @Published var isOpen = false
90	    @Published var isFullscreen = false
91	    @Published var selectedIndex = 0
92	    @Published var currentSectionIndex = 0
93	    var actions: [QuickAction] = []
94	
95	    private static let canonicalOrder = ["Input", "Terminal", "Workspace", "AI"]
96	
97	    var sectionOrder: [String] {
98	        let present = Set(actions.map(\.section))
99	        return Self.canonicalOrder.filter { present.contains($0) }
100	    }
101	
102	    var currentSection: String {
103	        let order = sectionOrder
104	        guard !order.isEmpty else { return "" }
105	        guard order.indices.contains(currentSectionIndex) else { return order[0] }
106	        return order[currentSectionIndex]
107	    }
108	
109	    var currentSectionActions: [(Int, QuickAction)] {
110	        actions.enumerated().filter { $0.element.section == currentSection }.map { ($0.offset, $0.element) }
111	    }
112	
113	    func open(with actions: [QuickAction]) {
114	        self.actions = actions
115	        currentSectionIndex = 0
116	        // Nothing to show if every section is hidden and there are no custom
117	        // actions — bail instead of subscripting an empty sectionOrder.
118	        guard let firstSection = sectionOrder.first else { return }
119	        selectedIndex = actions.firstIndex(where: { $0.section == firstSection }) ?? 0
120	        isOpen = true
121	        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
122	    }
123	
124	    func dismiss() {
125	        isOpen = false
126	        actions = []
127	    }
128	
129	    func cycle() {
130	        let sectionItems = currentSectionActions
131	        guard !sectionItems.isEmpty else { return }
132	        if let currentPos = sectionItems.firstIndex(where: { $0.0 == selectedIndex }) {
133	            let nextPos = (currentPos + 1) % sectionItems.count
134	            selectedIndex = sectionItems[nextPos].0
135	        } else {
136	            selectedIndex = sectionItems[0].0
137	        }
138	        UISelectionFeedbackGenerator().selectionChanged()
139	    }
140	
141	    func nextSection() {
142	        let count = sectionOrder.count
143	        guard count > 0 else { return }
144	        currentSectionIndex = (currentSectionIndex + 1) % count
145	        // Select first item in new section
146	        if let first = currentSectionActions.first {
147	            selectedIndex = first.0
148	        }
149	        UISelectionFeedbackGenerator().selectionChanged()
150	    }
151	
152	    func prevSection() {
153	        let count = sectionOrder.count
154	        guard count > 0 else { return }
155	        currentSectionIndex = (currentSectionIndex - 1 + count) % count
156	        if let first = currentSectionActions.first {
157	            selectedIndex = first.0
158	        }
159	        UISelectionFeedbackGenerator().selectionChanged()
160	    }
161	
162	    func execute() {
163	        guard actions.indices.contains(selectedIndex) else { return }
164	        actions[selectedIndex].action()
165	        UIImpactFeedbackGenerator(style: .light).impactOccurred()
166	        dismiss()
167	    }
168	}
