439	    private var surfaceLayout: some View {
440	        GeometryReader { geo in
441	            // iPhones report .compact width in both orientations, so size class
442	            // can't tell us portrait vs landscape — compare the actual bounds.
443	            let isLandscape = geo.size.width > geo.size.height
444	            // While composing, hide the secondaries so the focused terminal
445	            // gets the full screen alongside the keyboard.
446	            let hasSecondary = secondarySurfaces.count > 0 && !quickAction.isFullscreen && !keyboardActive
447	
448	            Group {
449	                if isLandscape {
450	                    landscapeLayout(size: geo.size, hasSecondary: hasSecondary)
451	                } else {
452	                    portraitLayout(size: geo.size, hasSecondary: hasSecondary)
453	                }
454	            }
455	            .padding(.horizontal, 12)
456	            .padding(.top, 8)
457	        }
458	    }
