460	    // Landscape: focused pane fills the left ~65%, secondaries stack in a
461	    // vertical scroll sidebar on the right.
462	    private func landscapeLayout(size: CGSize, hasSecondary: Bool) -> some View {
463	        let mainWidth = hasSecondary ? size.width * 0.65 : size.width
464	        let sideWidth = size.width * 0.35
465	        return HStack(spacing: 8) {
466	            if let surface = focusedSurface {
467	                focusedCard(for: surface, contentScale: 1.0)
468	                    .frame(width: mainWidth - (hasSecondary ? 4 : 16))
469	            }
470	            if hasSecondary {
471	                ScrollView(.vertical, showsIndicators: false) {
472	                    VStack(spacing: 6) {
473	                        ForEach(secondarySurfaces) { surface in
474	                            secondaryTile(for: surface)
475	                                .frame(height: tileHeight(for: secondarySurfaces.count, in: size.height))
476	                        }
477	                    }
478	                }
479	                .frame(width: sideWidth - 4)
480	            }
481	        }
482	    }
483	
484	    // Portrait: focused pane fills the width up top, secondaries sit in a
485	    // horizontal scroll row below — each tile gets a usable width instead of
486	    // being crushed into a narrow side column.
487	    private func portraitLayout(size: CGSize, hasSecondary: Bool) -> some View {
488	        let rowHeight: CGFloat = hasSecondary ? max(110, size.height * 0.24) : 0
489	        let tileWidth = max(150, size.width * 0.44)
490	        return VStack(spacing: 8) {
491	            if let surface = focusedSurface {
492	                focusedCard(for: surface, contentScale: 1.25)
493	                    .frame(maxWidth: .infinity, maxHeight: .infinity)
494	            }
495	            if hasSecondary {
496	                ScrollView(.horizontal, showsIndicators: false) {
497	                    HStack(spacing: 6) {
498	                        ForEach(secondarySurfaces) { surface in
499	                            secondaryTile(for: surface)
500	                                .frame(width: tileWidth, height: rowHeight)
501	                        }
502	                    }
503	                }
504	                .frame(height: rowHeight)
505	            }
506	        }
507	    }
