509	    // Focused surface card with its cycle/quick-action gestures.
510	    private func focusedCard(for surface: Surface, contentScale: CGFloat) -> some View {
511	        PaneCardView(
512	            title: surface.title,
513	            isFocused: true,
514	            hasNotification: appState.hasNotification(for: surface),
515	            isTranscribing: speechManager.isRecording,
516	            transcript: speechManager.transcript,
517	            terminalText: surface.isBrowser ? "" : (appState.surfaceContent[surface.id] ?? ""),
518	            contentScale: contentScale,
519	            isBrowser: surface.isBrowser,
520	            browserURL: appState.browserURLs[surface.id] ?? "",
521	            canOpenHistory: surface.isClaudeAgent,
522	            onOpenHistory: {
523	                // Resolve the CURRENTLY focused surface at fire time rather than
524	                // capturing this card's `surface`. During a cycle transition the
525	                // outgoing focused card stays mounted (and keeps firing scroll
526	                // callbacks) for the animation's duration, so a captured id would
527	                // open history for the surface you just left. Reading live focus
528	                // guarantees history always matches what's on screen.
529	                let focused = appState.surfaces.first(where: { $0.id == appState.focusedSurfaceID })
530	                    ?? surface
531	                guard focused.isClaudeAgent else { return }
532	                appState.presentedHistory = HistoryTarget(id: focused.id, title: focused.title)
533	            }
534	        )
535	        .id(surface.id)
536	        .transition(.asymmetric(
537	            insertion: .move(edge: cycleDirection).combined(with: .opacity),
538	            removal: .move(edge: cycleDirection == .trailing ? .leading : .trailing).combined(with: .opacity)
539	        ))
540	        .onLongPressGesture(minimumDuration: 0.4) {
541	            openQuickActions()
542	        }
543	        .highPriorityGesture(
544	            DragGesture(minimumDistance: 50)
545	                .onEnded { value in
546	                    guard !quickAction.isOpen else { return }
547	                    let dx = value.translation.width
548	                    let dy = value.translation.height
549	                    // Only act on a clearly horizontal swipe. Vertical/diagonal
550	                    // drags are terminal scrolling — a scroll must never switch
551	                    // surfaces. Require real horizontal travel AND horizontal
552	                    // dominance over vertical.
553	                    guard abs(dx) > 60, abs(dx) > abs(dy) * 1.8 else { return }
554	                    if speechManager.isRecording {
555	                        // Horizontal swipe while recording opens transcript editor
556	                        editingText = speechManager.stop()
557	                        volumeHandler.clearSpeechState()
558	                        isEditingTranscript = true
559	                        return
560	                    }
561	                    if dx < 0 {
562	                        cycleDirection = .trailing
563	                        withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
564	                            appState.cycleSurface()
565	                        }
566	                    } else {
567	                        cycleDirection = .leading
568	                        withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
569	                            appState.cycleSurfaceBackward()
570	                        }
571	                    }
572	                },
573	            including: .gesture
574	        )
575	    }
