739	    // MARK: - Content polling
740	
741	    @State private var pollCycleCount = 0
742	
743	    private func startContentPolling() {
744	        // Tear down any existing timer first — onAppear/foreground can fire more
745	        // than once, and a duplicate timer means double polling and wasted RPCs.
746	        contentPollTimer?.invalidate()
747	        contentPollTimer = nil
748	        // Initial fetch — focused only
749	        if let focused = focusedSurface {
750	            fetchContent(for: focused)
751	        }
752	        contentPollTimer = Timer.scheduledTimer(withTimeInterval: 3.0, repeats: true) { [weak appState] _ in
753	            Task { @MainActor in
754	                guard let appState else { return }
755	                self.pollCycleCount += 1
756	                let focusedID = appState.focusedSurfaceID
757	                // Focused surface every cycle, secondary every 5th (~15s)
758	                for surface in appState.surfaces {
759	                    if surface.id == focusedID {
760	                        self.fetchContent(for: surface)
761	                    } else if self.pollCycleCount % 5 == 0 {
762	                        self.fetchContent(for: surface)
763	                    }
764	                }
765	            }
766	        }
767	    }
768	
769	    private func fetchContent(for surface: Surface) {
770	        if surface.isBrowser {
771	            appState.readBrowserURL(surface.id)
772	        } else {
773	            // Live terminal mirror: deep read when focused (scrollback for plain
774	            // shells), cheap preview otherwise. Claude conversation history is a
775	            // separate on-demand full-screen viewer, not this inline content.
