import Foundation

// Mirror of TerminalTextRenderer's link pass (TerminalTextView.swift) for
// offline verification of the wrap-joining behavior.

let linkDetector = try! NSDataDetector(types: NSTextCheckingResult.CheckingType.link.rawValue)

let urlScalars: CharacterSet = {
    var set = CharacterSet.alphanumerics
    set.insert(charactersIn: "-._~:/?#[]@!$&'()*+,;=%")
    return set
}()
let minWrapWidth = 40

func lineRanges(of ns: NSString) -> [NSRange] {
    var ranges: [NSRange] = []
    var start = 0
    while start <= ns.length {
        let rest = NSRange(location: start, length: ns.length - start)
        let newline = ns.range(of: "\n", options: [], range: rest)
        if newline.location == NSNotFound {
            ranges.append(rest)
            break
        }
        ranges.append(NSRange(location: start, length: newline.location - start))
        start = newline.location + newline.length
    }
    return ranges
}

func joinedAcrossWraps(
    _ match: NSTextCheckingResult, in ns: NSString, lines: [NSRange], maxLineLength: Int
) -> (NSRange, URL)? {
    guard maxLineLength >= minWrapWidth else { return nil }
    let matchEnd = match.range.location + match.range.length
    guard var lineIndex = lines.firstIndex(where: {
        NSLocationInRange(match.range.location, $0) && matchEnd == $0.location + $0.length
    }), lines[lineIndex].length == maxLineLength else { return nil }

    var urlString = ns.substring(with: match.range)
    var end = matchEnd
    while lineIndex + 1 < lines.count {
        let next = lines[lineIndex + 1]
        let nextText = ns.substring(with: next)
        let continuation = String(nextText.unicodeScalars.prefix(while: urlScalars.contains))
        guard !continuation.isEmpty else { break }
        urlString += continuation
        end = next.location + (continuation as NSString).length
        guard end == next.location + next.length, next.length == maxLineLength else { break }
        lineIndex += 1
    }
    guard end > matchEnd, let url = URL(string: urlString) else { return nil }
    return (NSRange(location: match.range.location, length: end - match.range.location), url)
}

func links(in text: String) -> [(String, String)] {
    let ns = text as NSString
    let matches = linkDetector.matches(in: text, range: NSRange(location: 0, length: ns.length))
    let lines = lineRanges(of: ns)
    let maxLineLength = lines.reduce(0) { max($0, $1.length) }
    var linkedEnd = 0
    var out: [(String, String)] = []
    for match in matches {
        guard match.range.location >= linkedEnd else { continue }
        var range = match.range
        var url = match.url
        if let joined = joinedAcrossWraps(match, in: ns, lines: lines, maxLineLength: maxLineLength) {
            range = joined.0
            url = joined.1
        }
        guard let url else { continue }
        out.append((ns.substring(with: range), url.absoluteString))
        linkedEnd = range.location + range.length
    }
    return out
}

var failures = 0
func check(_ name: String, _ text: String, expectURLs: [String]) {
    let got = links(in: text).map { $0.1 }
    if got == expectURLs {
        print("PASS \(name)")
    } else {
        failures += 1
        print("FAIL \(name)\n  expected: \(expectURLs)\n  got:      \(got)")
    }
}

// Case 1: the reported bug — 80-col terminal hard-wraps a long URL.
let full = "https://ms-mac-mini.tail901772.ts.net/wrinkles/onepager/business_os_landscape.html"
let head = "Visit " + String(full.prefix(74))   // 80-char row, cut mid-URL
let tail = String(full.dropFirst(74))            // "e.html"-style remainder
let chrome = String(repeating: "─", count: 80)   // another full-width row (TUI chrome)
check("wrapped URL rejoined", chrome + "\n" + head + "\n" + tail + " to see it",
      expectURLs: [full])

// Case 2: URL spanning three full rows.
let path = String(repeating: "abc/", count: 45)  // long path
let url3 = "https://example.com/" + path + "index.html"
let r1 = String(url3.prefix(80))
let r2 = String(url3.dropFirst(80).prefix(80))
let r3 = String(url3.dropFirst(160))
check("three-row wrap", r1 + "\n" + r2 + "\n" + r3, expectURLs: [url3])

// Case 3: short line ending in a complete URL, prose on next line — no join.
check("short line no join", "See https://example.com\nand more text here",
      expectURLs: ["https://example.com"])

// Case 4: full-width line NOT ending mid-URL (URL earlier in the row) — no join.
let padded = "https://example.com is the site we deploy to, remember that padding padding!"
check("url mid-row no join", String(repeating: "═", count: padded.count) + "\n" + padded + "\nnext.html is a file",
      expectURLs: ["https://example.com"])

// Case 5: continuation that itself re-matches as a link is swallowed, not doubled.
let full5 = "https://docs.example.com/guide/getting-started/installation-on-macos/site.com/page.html"
let h5 = String(full5.prefix(80))
let t5 = String(full5.dropFirst(80))
check("tail re-match skipped", h5 + "\n" + t5, expectURLs: [full5])

print(failures == 0 ? "ALL PASS" : "\(failures) FAILURES")
exit(failures == 0 ? 0 : 1)

